export {
  itemView,
  menuView,
  popupView,
  rootView,
  separatorView,
  triggerView,
} from "../../../foldkit/ui/menubar";
export type {
  ItemViewConfig,
  MenubarStyle,
  MenuViewConfig,
  PopupViewConfig,
  RootViewConfig,
  TriggerViewConfig,
} from "../../../foldkit/ui/menubar";

export {
  shadcnMenubarItemClasses,
  shadcnMenubarMenuClasses,
  shadcnMenubarPopupClasses,
  shadcnMenubarRootClasses,
  shadcnMenubarSeparatorClasses,
  shadcnMenubarTriggerClasses,
} from "./view";

export {
  menubarItemClasses as shadcnMenubarItemClasses,
  menubarMenuClasses as shadcnMenubarMenuClasses,
  menubarPopupClasses as shadcnMenubarPopupClasses,
  menubarRootClasses as shadcnMenubarRootClasses,
  menubarSeparatorClasses as shadcnMenubarSeparatorClasses,
  menubarTriggerClasses as shadcnMenubarTriggerClasses,
} from "../../../foldkit/ui/menubar/view";

import { describe, expect, test } from "vitest";

import * as Menubar from "./index";

describe("shadcn Menubar registry view", () => {
  test("reuses the Foldkit Menubar view contract", () => {
    expect(Menubar.rootView).toBeTypeOf("function");
    expect(Menubar.triggerView).toBeTypeOf("function");
    expect(Menubar.popupView).toBeTypeOf("function");
    expect(Menubar.shadcnMenubarRootClasses).toContain("border");
  });
});
